  `${relatorio.total_acompanhadas} oportunidades acompanhadas`,
  `${relatorio.total_avancaram} avançaram · ${relatorio.total_resolvidas} foram resolvidas`,
  `${relatorio.total_paradas} continuam paradas · ${relatorio.total_perdidas} foram perdidas`,
  '',
  'Principais ações para começar a semana:',
  acoes,
  '',
  '<Ver relatório semanal>',
].join('\n');
const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: texto.replace('<Ver relatório semanal>', '') } },
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Ver relatório semanal', emoji: true }, url: reportUrl, action_id: 'abrir_radar_semanal' }] },
];
const metadata = {
  empresa_id: relatorio.empresa_id, semana_inicio: relatorio.semana_inicio, semana_fim: relatorio.semana_fim,
  bucket_id: 'tmc-radar-relatorios', object_path: agregado.object_path, report_url: reportUrl,
  html_bytes: Number($('Semanal — Renderiza HTML').first().json.html?.length || 0),
  total_acompanhadas: relatorio.total_acompanhadas, total_novas: relatorio.total_novas,
  total_avancaram: relatorio.total_avancaram, total_resolvidas: relatorio.total_resolvidas,
  total_paradas: relatorio.total_paradas, total_perdidas: relatorio.total_perdidas,
  taxa_movimento: relatorio.taxa_movimento, slack_payload: { text: texto, blocks }, gerado_em: relatorio.gerado_em_iso,
};
return [{ json: { relatorio, report_url: reportUrl, slack_preview: texto.replace('<Ver relatório semanal>', reportUrl), slack_blocks: blocks, metadata_base64: Buffer.from(JSON.stringify(metadata),'utf8').toString('base64'), aviso: 'PRÉVIA SOMENTE — nenhum node de envio ao Slack está conectado.' } }];

return $input.all().map((item) => {
  const dados = item.json;

  const historico = String(dados.historico ?? '').trim();
  const mensagensCarregadas = Number(dados.mensagens_carregadas ?? 0);

  // Procura nomes escritos pelos vendedores:
  // *Thiago:*, *Raphael:*, *Alexandre:* etc.
  const nomesEncontrados = [
    ...historico.matchAll(/\*([^*:\n]{2,40}):\*/g),
  ].map((resultado) => resultado[1].trim());

  // O último nome escrito no histórico tende a ser o vendedor atual.
  const vendedorDoHistorico =
    nomesEncontrados.length > 0
      ? nomesEncontrados[nomesEncontrados.length - 1]
      : null;

  const vendedorParaAnalise =
    vendedorDoHistorico ||
    dados.nome_vendedor_capturado ||
    'Não identificado';

  const limiteHistoricoAtingido = mensagensCarregadas >= 40;

  const textoParaAnalise = [
    'DADOS DA CONVERSA',
    `Chave: ${dados.chave_conversa}`,
    `Loja: ${dados.codigo_loja}`,
    `Cliente: ${dados.nome_cliente || 'Não identificado'}`,
    `Vendedor provável: ${vendedorParaAnalise}`,
    `Mensagens carregadas: ${mensagensCarregadas}`,
    `Limite de 40 atingido: ${limiteHistoricoAtingido ? 'sim' : 'não'}`,
    '',
    'HISTÓRICO',
    historico,
  ].join('\n');

  return {
    json: {
      ...dados,
      mensagens_carregadas: mensagensCarregadas,
      vendedor_para_analise: vendedorParaAnalise,
      limite_historico_atingido: limiteHistoricoAtingido,
      texto_para_analise: textoParaAnalise,
    },
  };
});

let registros = $input.all().map((item) => item.json);

if (!registros.some((item) => item.chave_conversa)) {
  registros = $('Salva Classificação do Dia').all().map((item) => item.json);
}

registros = registros.filter((item) => item && item.chave_conversa);

const pesoPrioridade = {
  alta: 0,
  media: 1,
  baixa: 2,
  nenhuma: 3,
};

const oportunidades = registros
  .filter((item) =>
    Boolean(item.precisa_acao) &&
    item.status === 'aberta' &&
    item.prioridade !== 'nenhuma' &&
    Number(item.confianca || 0) >= 70
  )
  .sort((a, b) => {
    const prioridade = (pesoPrioridade[a.prioridade] ?? 9) - (pesoPrioridade[b.prioridade] ?? 9);
    if (prioridade !== 0) return prioridade;

    const dataA = new Date(a.ultima_mensagem_historico || 0).getTime();
    const dataB = new Date(b.ultima_mensagem_historico || 0).getTime();
    if (dataA !== dataB) return dataA - dataB;

    return Number(b.confianca || 0) - Number(a.confianca || 0);
  });

const agora = $now.setZone('America/Sao_Paulo');
const dataReferenciaIso = registros[0]?.data_referencia || agora.toISODate();
const [ano, mes, dia] = dataReferenciaIso.split('-');

const relatorio = {
  empresa_id: registros[0]?.empresa_id || '8c26ce87-8096-4010-b8c4-6164648e8d6c',
  data_referencia_iso: dataReferenciaIso,
  data_referencia: `${dia}/${mes}/${ano}`,
  gerado_em: agora.toFormat("dd/LL/yyyy 'às' HH:mm"),
  gerado_em_iso: agora.toISO(),
  conversas_analisadas: registros.length,
  total_oportunidades: oportunidades.length,
  prioridade_alta: oportunidades.filter((item) => item.prioridade === 'alta').length,
  prioridade_media: oportunidades.filter((item) => item.prioridade === 'media').length,
  prioridade_baixa: oportunidades.filter((item) => item.prioridade === 'baixa').length,
  principais_acoes: oportunidades.slice(0, 3).map((item) => ({
    cliente: item.nome_cliente || 'Cliente não identificado',
    acao: item.acao_recomendada || 'Revisar conversa',
  })),
  oportunidades,
};

return [{ json: { relatorio } }];

const relatorio = $json.relatorio;

function escapeHtml(valor) {
  return String(valor ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function telefoneWhatsApp(valor) {
  const digitos = String(valor ?? '').replace(/\D/g, '');
  if (!digitos) return '';
  return digitos.startsWith('55') ? digitos : `55${digitos}`;
}

function rotuloTipo(tipo) {
  const rotulos = {
    cliente_aguardando: 'Cliente aguardando',
    promessa_pendente: 'Promessa pendente',
    orcamento_sem_retorno: 'Orçamento sem retorno',
    duvida_sem_resposta: 'Dúvida sem resposta',
    negociacao_em_andamento: 'Negociação em andamento',
    produto_indisponivel: 'Produto indisponível',
    outro: 'Outra oportunidade',
  };
  return rotulos[tipo] || 'Oportunidade comercial';
}

function renderCard(item, indice) {
  const prioridade = ['alta', 'media', 'baixa'].includes(item.prioridade)
    ? item.prioridade
    : 'baixa';
  const telefone = telefoneWhatsApp(item.telefone_normalizado);
  const whatsapp = telefone
    ? `<a class="whatsapp" href="https://wa.me/${telefone}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a>`
    : '<span class="sem-telefone">Telefone não disponível</span>';

  return `
    <article class="oportunidade prioridade-${prioridade}">
      <div class="topo-card">
        <div>
          <span class="ordem">${indice + 1}</span>
          <h2>${escapeHtml(item.nome_cliente || 'Cliente não identificado')}</h2>
          <p class="meta">${escapeHtml(item.vendedor_responsavel || item.vendedor_detectado || 'Vendedor não identificado')} · Loja ${escapeHtml(item.codigo_loja || 'não identificada')}</p>
        </div>
        <span class="prioridade">${escapeHtml(prioridade.toUpperCase())}</span>
      </div>
      <div class="tipo">${escapeHtml(rotuloTipo(item.tipo_oportunidade))}</div>
      <section>
        <h3>O que está acontecendo</h3>
        <p>${escapeHtml(item.resumo || 'Sem resumo disponível.')}</p>
      </section>
      <section class="evidencia">
        <h3>Evidência encontrada</h3>
        <p>${escapeHtml(item.evidencia || 'Sem evidência registrada.')}</p>
      </section>
      <section class="acao">
        <div>
          <h3>Próxima ação recomendada</h3>
          <p>${escapeHtml(item.acao_recomendada || 'Revisar a conversa.')}</p>
        </div>
        ${whatsapp}
      </section>
    </article>`;
}

const cards = relatorio.oportunidades.length
  ? relatorio.oportunidades.map(renderCard).join('\n')
  : `
    <div class="vazio">
      <h2>Nenhuma oportunidade acionável encontrada</h2>
      <p>As conversas foram analisadas, mas nenhuma atingiu os critérios de ação e confiança deste relatório.</p>
    </div>`;

